import Ajv from 'ajv';
const ajv = new Ajv({strict: false, validateFormats: false});
try {
  ajv.compile({type: 'object', properties: {location: {type: 'not-a-json-schema-type'}}});
  console.log('COMPILED (no throw)');
} catch (e) { console.log('THROWS:', e.message); }
const v = ajv.compile({type: 'object', properties: {ssn: {type: 'string'}}, required: ['ssn']});
console.log('type-reject:', JSON.stringify((v({ssn: 123456789}), v.errors)));
console.log('extra-prop:', v({ssn: 'x', extra: 'y'}));
console.log('enum:', JSON.stringify((v2 => (v2({s: 'zzz'}), v2.errors))(ajv.compile({type:'object', properties:{s:{enum:['a','b']}}, required:['s']}))));
